repo.harvests.py:
"""Harvest records."""


class Harvest:
    def __init__(self, field, kilos):
        self.field = field
        self.kilos = kilos

    def __repr__(self):
        return "Harvest(%r, %r)" % (self.field, self.kilos)


ROWS = [('upper', 34), ('hill', 36), ('upper', 17), ('lower', 46), ('hill', 42), ('hill', 54)]


def load_harvests():
    """Yield the stored harvests one at a time."""
    for field, kilos in ROWS:
        yield Harvest(field, kilos)

repo.changes.py:
"""Changes in kilos from one harvest to the next."""


def kilos_changes(harvests):
    """Return the change in kilos from each harvest to the next: one entry for every neighbouring pair."""
    out = []
    for i in range(2, len(harvests)):
        out.append(harvests[i].kilos - harvests[i - 1].kilos)
    return out


def biggest_rise(harvests):
    """Return the largest increase between neighbours, or 0 when there is none."""
    rises = [c for c in kilos_changes(harvests) if c > 0]
    return max(rises) if rises else 0


def largest_kilos(harvests):
    """Return the largest kilos, or None when there are no harvests."""
    values = [x.kilos for x in harvests]
    return max(values) if values else None


def describe_harvest(harvest):
    """Return a one-line description of a harvest."""
    return "%s: %s" % (harvest.field, harvest.kilos)

