from harvests import load_harvests, ROWS
from changes import kilos_changes


def test_number_of_changes():
    assert len(kilos_changes(list(load_harvests()))) == len(ROWS) - 1


def test_single_item():
    assert kilos_changes(list(load_harvests())[:1]) == []
